"""Independent geometry and invariant checks for the wallpaper utility."""

import itertools
import random
import unittest

from src.component import calculate_black_area_doubled


def geometric_cell_area_doubled(x, y):
    """Count black half-squares using exact triangle-centroid coordinates.

    Away from boundaries, crossing each of x = integer, y = even, or
    x + y = even flips the parity of the sum of their floor functions.
    The centroids (x + t/3, y + t/3), t = 1, 2, sample the two halves
    of a unit square without touching any wallpaper line.
    """
    return sum(
        (x + (3 * y + t) // 6 + (3 * (x + y) + 2 * t) // 6) % 2 == 0
        for t in (1, 2)
    )


class WallpaperTests(unittest.TestCase):
    def test_specification_examples(self):
        self.assertEqual(calculate_black_area_doubled(0, 0, 3, 3), 10)
        self.assertEqual(calculate_black_area_doubled(-1, -2, 1, 3), 11)
        self.assertEqual(
            calculate_black_area_doubled(-10**9, -10**9, 10**9, 10**9),
            4_000_000_000_000_000_000,
        )

    def test_all_small_rectangles_against_geometry(self):
        coordinates = range(-6, 7)
        cells = {
            (x, y): geometric_cell_area_doubled(x, y)
            for x in coordinates
            for y in coordinates
        }
        for a, c in itertools.combinations(coordinates, 2):
            for b, d in itertools.combinations(coordinates, 2):
                expected = sum(
                    cells[x, y] for x in range(a, c) for y in range(b, d)
                )
                with self.subTest(rectangle=(a, b, c, d)):
                    self.assertEqual(
                        calculate_black_area_doubled(a, b, c, d), expected
                    )

    def test_unit_cells_at_coordinate_limits(self):
        for x in (-10**9, -10**9 + 1, -1, 0, 1, 10**9 - 2, 10**9 - 1):
            for y in (-10**9, -10**9 + 1, -1, 0, 1, 10**9 - 2, 10**9 - 1):
                self.assertEqual(
                    calculate_black_area_doubled(x, y, x + 1, y + 1),
                    geometric_cell_area_doubled(x, y),
                )

    def test_large_rectangle_invariants(self):
        rng = random.Random(6485)
        for _ in range(2000):
            a, c = sorted(rng.sample(range(-10**8, 10**8), 2))
            b, d = sorted(rng.sample(range(-10**8, 10**8), 2))
            actual = calculate_black_area_doubled(a, b, c, d)
            self.assertIsInstance(actual, int)
            self.assertGreaterEqual(actual, 0)
            self.assertLessEqual(actual, 2 * (c - a) * (d - b))
            dx = 4 * rng.randint(-10**8, 10**8)
            dy = 2 * rng.randint(-10**8, 10**8)
            self.assertEqual(
                calculate_black_area_doubled(a + dx, b + dy, c + dx, d + dy),
                actual,
            )
            if c - a > 1:
                x = rng.randrange(a + 1, c)
                self.assertEqual(
                    calculate_black_area_doubled(a, b, x, d)
                    + calculate_black_area_doubled(x, b, c, d),
                    actual,
                )
            if d - b > 1:
                y = rng.randrange(b + 1, d)
                self.assertEqual(
                    calculate_black_area_doubled(a, b, c, y)
                    + calculate_black_area_doubled(a, y, c, d),
                    actual,
                )


if __name__ == '__main__':
    unittest.main()
